<?php
declare(strict_types=1);
if (!defined('LIBRARY_ENTRY')) { http_response_code(404); exit; }
return <<<'LIBRARY_VIEW'
<!doctype html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Leaf &amp; Ledger | Library management</title><link rel="stylesheet" href="assets/style.css"><script src="assets/app.js" defer></script></head>
<body><div class="shell"><aside class="sidebar"><a class="brand" href="index.php"><span class="brand-mark" aria-hidden="true">L</span><span>Leaf &amp; Ledger<small>LIBRARY MANAGEMENT</small></span></a><div class="nav-label">WORKSPACE</div><nav aria-label="Main navigation"><a class="nav {% if catalog %}active{% endif %}" href="index.php">▤ &nbsp; Book catalogue</a>{% if auth %}<a class="nav {% if form %}active{% endif %}" href="index.php?page=add">＋ &nbsp; Add book</a>{% endif %}<a class="nav {% if contact %}active{% endif %}" href="index.php?page=contact">◇ &nbsp; About &amp; help</a></nav><div class="account"><div class="nav-label">ACCOUNT</div>{% if auth %}<p>Signed in as <strong>{{ username }}</strong></p><form action="index.php?page=logout" method="post"><input type="hidden" name="csrf" value="{{ csrf }}"><button class="side-button">Sign out</button></form>{% else %}<p>Manage the catalogue with a librarian account.</p><a class="side-button" href="index.php?page=login">Librarian sign in →</a>{% endif %}</div><div class="side-foot">5CS045 · Library project</div></aside>
<main><header class="topbar"><span>Library workspace / {% if catalog %}Catalogue{% else %}Administration{% endif %}</span><span class="top-badge">LIBRARY CATALOGUE</span></header>
{% if flash %}<div class="notice" role="status">{{ flash }}</div>{% endif %}
{% if errors %}<div class="alert" role="alert"><strong>Check the following</strong><ul>{% for error in errors %}<li>{{ error }}</li>{% endfor %}</ul></div>{% endif %}
{% if catalog %}
<section class="hero"><div><p class="eyebrow">YOUR CAMPUS · YOUR COLLECTION</p><h1>Discover more.<br><em> Read beyond.</em></h1><p>Explore the catalogue or sign in to maintain the library inventory.</p>{% if auth %}<a class="button light" href="index.php?page=add">＋ Add a book</a>{% else %}<a class="button light" href="#catalogue">Explore catalogue ↓</a>{% endif %}</div><div class="hero-art" aria-hidden="true"><div class="book b1"></div><div class="book b2"></div><div class="book b3"></div><div class="book b4"></div><div class="book b5"></div><div class="shelf"></div></div></section>
<div class="stats"><div><span>Total titles</span><strong>{{ stats.titles }}</strong><small>Books in the catalogue</small></div><div><span>Genres</span><strong>{{ stats.genres }}</strong><small>Different categories</small></div><div><span>Copies</span><strong>{{ stats.copies }}</strong><small>Physical inventory</small></div></div>
<section class="panel" id="catalogue"><div class="panel-head"><div><p class="eyebrow">COLLECTION</p><h2>Book catalogue</h2><p>Filter by title, author, genre and year together.</p></div>{% if auth %}<a class="button" href="index.php?page=add">＋ Add book</a>{% endif %}</div>
<form class="filters" id="search-form" action="index.php" method="get"><label>Title<input type="search" name="title" value="{{ filters.title }}" maxlength="150" placeholder="Search titles"></label><label>Author<input type="search" name="author" value="{{ filters.author }}" maxlength="120" placeholder="Author name"></label><label>Genre<select name="genre"><option value="">All genres</option>{% for g in genres %}<option value="{{ g.name }}" {% if g.selected %}selected{% endif %}>{{ g.name }}</option>{% endfor %}</select></label><label>Year<input type="number" name="year" min="1" max="{{ max_year }}" value="{{ filters.year }}" placeholder="2023"></label><div class="filter-actions"><button class="button" type="submit">Search</button><a class="secondary" href="index.php">Reset</a></div></form>
<div class="result-head"><span id="result-count" role="status" aria-live="polite">{{ count }} titles found</span><span class="muted">Live search enabled</span></div><div class="table-wrap"><table><thead><tr><th>Title / Author</th><th>Genre</th><th>Year</th><th>ISBN</th><th>Copies</th><th>Availability</th>{% if auth %}<th>Actions</th>{% endif %}</tr></thead><tbody id="book-rows" data-auth="{% if auth %}1{% else %}0{% endif %}">{% for b in books %}<tr><td><strong>{{ b.title }}</strong><small>{{ b.author }}</small></td><td>{{ b.genre }}</td><td>{{ b.publication_year }}</td><td>{{ b.isbn }}</td><td>{{ b.copies }}</td><td>{% if b.available %}<span class="pill">In stock</span>{% else %}<span class="pill out">No copies</span>{% endif %}</td>{% if auth %}<td><div class="actions"><a href="index.php?page=edit&amp;id={{ b.id }}">Edit</a><a class="danger-link" href="index.php?page=delete&amp;id={{ b.id }}">Delete</a></div></td>{% endif %}</tr>{% endfor %}</tbody></table></div><p id="empty-state" class="empty" {% if has_books %}hidden{% endif %}>No books match these filters.</p></section>
{% endif %}
{% if login %}<section class="panel narrow"><p class="eyebrow">SECURE ACCESS</p><h1>Librarian sign in</h1><p>Sign in to add, edit and remove books.</p><form method="post" action="index.php?page=login" class="stack"><input type="hidden" name="csrf" value="{{ csrf }}"><label>Username<input name="username" autocomplete="username" required maxlength="40"></label><label>Password<input type="password" name="password" autocomplete="current-password" required maxlength="72"></label><label>CAPTCHA: What is {{ captcha }}?<input name="captcha" inputmode="numeric" autocomplete="off" required maxlength="3"></label><button class="button">Sign in</button><a href="index.php">Back to catalogue</a></form><p class="muted">Administrator accounts are created privately by the site owner.</p></section>{% endif %}
{% if form %}<section class="panel narrow"><p class="eyebrow">CATALOGUE MANAGEMENT</p><h1>{% if edit %}Edit book{% else %}Add a book{% endif %}</h1><p>Complete the details below to save a catalogue record.</p><form class="stack" method="post" action="index.php?page={% if edit %}edit&amp;id={{ id }}{% else %}add{% endif %}"><input type="hidden" name="csrf" value="{{ csrf }}"><label>Title<input name="title" maxlength="150" required value="{{ book.title }}"></label><label>Author<input name="author" maxlength="120" required value="{{ book.author }}"></label><div class="form-grid"><label>Genre<select name="genre" required><option value="">Choose genre</option>{% for g in genres %}<option value="{{ g.name }}" {% if g.selected %}selected{% endif %}>{{ g.name }}</option>{% endfor %}</select></label><label>Publication year<input name="publication_year" type="number" min="1" max="{{ max_year }}" required value="{{ book.publication_year }}"></label><label>ISBN (optional)<input name="isbn" maxlength="20" value="{{ book.isbn }}"></label><label>Copies<input name="copies" type="number" min="0" max="10000" required value="{{ book.copies }}"></label></div><div class="actions"><button class="button">Save book</button><a class="secondary" href="index.php">Cancel</a></div></form></section>{% endif %}
{% if delete %}<section class="panel narrow"><p class="eyebrow">CONFIRM REMOVAL</p><h1>Delete this book?</h1><p>You are about to remove <strong>{{ book.title }}</strong> by {{ book.author }} from the catalogue. This action cannot be undone.</p><form method="post" action="index.php?page=delete&amp;id={{ id }}" class="actions"><input type="hidden" name="csrf" value="{{ csrf }}"><button class="button danger">Delete permanently</button><a class="secondary" href="index.php">Cancel</a></form></section>{% endif %}
{% if contact %}<section class="panel narrow"><p class="eyebrow">ABOUT THE PROJECT</p><h1>Library help</h1><p>Leaf &amp; Ledger is a student library catalogue that helps users find books and librarians maintain records.</p><h2>Using the catalogue</h2><p>Search by title or author, and combine genre and publication year to narrow results. Librarians can sign in to add, amend or remove books.</p><h2>Need assistance?</h2><p>Contact the librarian or site administrator responsible for this deployment.</p><a class="button" href="index.php">Return to catalogue</a></section>{% endif %}
{% if error_page %}<section class="panel narrow"><h1>Request unavailable</h1><p>Return to the catalogue or try again after checking the setup.</p><a class="button" href="index.php">Return to catalogue</a></section>{% endif %}
<footer>Leaf &amp; Ledger <span>·</span> Library Management System <span>·</span> PHP &amp; MySQL</footer></main></div></body></html>
LIBRARY_VIEW;
